import logging

logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())

licenceserver_configuration_template = '''
#### LICENCE SERVER CONFIGURATION BEGIN #######
MULT 192.168.10.9
SCFG SWL
STRT
forw swl setlicenseserver {licenceserver_ip} {licenceserver_port}
LSCI
#### LICENCE SERVER CONFIGURATION END #######
'''


class LicenceServerConfig(object):
    """TMA script for Licence server configuration."""

    def __init__(self, licenceserver_ip, licenceserver_port=5053):
        self.licenceserver_ip = licenceserver_ip
        self.licenceserver_port = licenceserver_port

    def __str__(self):
        return licenceserver_configuration_template.format(licenceserver_ip=self.licenceserver_ip,
                                                           licenceserver_port=self.licenceserver_port)

    def __add__(self, other):
        return str(self) + str(other)

    def __radd__(self, other):
        return str(other) + str(self)
